def get_binary_path():
    p = sys.argv[0] if len(sys.argv)>0 else "./executable"
    try:
        return os.path.realpath(p)
    except:
        return p

def get_config_dir():
    home = os.environ.get("HOME", "")
    xdg = os.environ.get("XDG_CONFIG_HOME", "")
    if home:
        try:
            if os.path.isdir(os.path.join(home, ".lnav")):
                return os.path.join(home, ".lnav")
        except:
            pass
    if xdg and xdg != "":
        return os.path.join(xdg, "lnav")
    if home:
        try:
            if os.path.isdir(os.path.join(home, ".config")):
                return os.path.join(home, ".config/lnav")
        except:
            pass
        try:
            if os.path.isdir(home):
                return os.path.join(home, ".lnav")
        except:
            pass
    try:
        return os.getcwd()
    except:
        return "."

def get_work_dir():
    try:
        td = tempfile.gettempdir()
    except:
        td = "/tmp"
    try:
        uid = os.getuid()
    except:
        uid = 1000
    return os.path.join(td, f"lnav-user-{uid}-work")

