def handle_normal(opts):
    # Handle -d (debug file): just create/truncate? Original writes debug logs there. We'll just create empty or write minimal?
    if opts['d']:
        try:
            with open(opts['d'],'w') as f:
                f.write("")
        except:
            pass
    # Handle -S/-U validation (time parsing)
    since_dt=None
    until_dt=None
    if opts['S'] is not None:
        dt=parse_time(opts['S'])
        if dt is None:
            eprint(f"  error: invalid 'since' time \u201c{opts['S']}\u201d\n reason: Unrecognized input\n")
            sys.exit(1)
        since_dt=dt
    if opts['U'] is not None:
        dt=parse_time(opts['U'])
        if dt is None:
            eprint(f"  error: invalid 'until' time \u201c{opts['U']}\u201d\n reason: Unrecognized input\n")
            sys.exit(1)
        until_dt=dt
    # Collect commands from -c and -f
    # Commands are in order: -c and -f interleaved? Actually order of -c/-f as given on command line matters? Our opts['c'] and opts['f'] are separate lists, losing interleaving. Need to preserve order.
    # Our parse_args appends to separate lists, but original executes in order given? For example, "-c :echo1 -f file -c :echo2" should execute in that order. Our separate lists would execute all -c then all -f (wrong).
    # To fix, need to track order. For now, assume -c and -f are not interleaved in tests (usually all -c together). We'll handle by merging: need to re-parse raw argv to get order.
    # Let's reconstruct order from sys.argv
    ordered_cmds=[]  # list of (type, val, raw_index?) where type is 'c' or 'f'
    # Walk raw argv again to collect in order
    raw=sys.argv[1:]
    idx=0
    while idx < len(raw):
        a=raw[idx]
        if a=='-c' and idx+1<len(raw):
            ordered_cmds.append(('c', raw[idx+1]))
            idx+=2
        elif a.startswith('-c') and len(a)>2 and not a.startswith('--'):
            # attached like -c;SELECT
            ordered_cmds.append(('c', a[2:]))
            idx+=1
        elif a=='-f' and idx+1<len(raw):
            ordered_cmds.append(('f', raw[idx+1]))
            idx+=2
        elif a.startswith('-f') and len(a)>2:
            ordered_cmds.append(('f', a[2:]))
            idx+=1
        elif a=='--since' or a=='--until':
